-- 016_add_50_verified_native_species.sql
-- LOCAL-ONLY migration for the Katutubong Puno project.
-- Adds 50 audited Philippine native/endemic trees after correcting synonyms,
-- spelling, endemicity claims, and six taxa whose documented native ranges do
-- not include the Philippines. Do not apply to the live VPS before local review.
--
-- Transaction handling: the project migration runner wraps each migration in a
-- transaction. For manual use: psql --single-transaction --set ON_ERROR_STOP=1.

SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '5min';

CREATE TEMP TABLE _species_016_input (
  desired_id uuid, scientific_name text, genus text, species_epithet text,
  family text, native_status text, description text, leaf_description text,
  bark_description text, flower_description text, fruit_description text,
  seed_description text, growth_form text, min_height_m numeric,
  max_height_m numeric, min_canopy_m numeric, max_canopy_m numeric,
  growth_rate text, fruit_bearing boolean, flowering boolean,
  conservation_status text, conservation_source text, submitted_name text,
  distribution_notes text, habitat_notes text
) ON COMMIT DROP;

INSERT INTO _species_016_input VALUES
  ('21f059b6-f5c2-50c9-aac0-5bc1106346c1', 'Xanthostemon verdugonianus', 'Xanthostemon', 'verdugonianus', 'Myrtaceae', 'endemic', 'Xanthostemon verdugonianus is a philippine endemic tree in Myrtaceae. CDFP habitat record: Lowland and medium elevation forests and regrowths on ultramafics. 700-800m (photos).', 'Leaves are simple, opposite, and leathery, with an intramarginal vein and fine oil glands typical of many Myrtaceae.', 'Bark is firm on young stems and becomes rough, fissured, or peeling with age; Tristaniopsis is especially noted for exfoliating bark.', 'Flowers have numerous conspicuous stamens; color and arrangement of the flower clusters are useful identification characters.', 'The dry capsule opens at maturity; the persistent calyx and capsule shape help confirm identity.', 'Several small seeds occur in each capsule and should be sown fresh after collection from a verified tree.', 'medium', 8, 25, 4, 12, 'moderate', TRUE, TRUE, 'Vulnerable', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Vulnerable', 'Xanthostemon verdugonianus', 'Endemic to the Philippines. BUCAS GRANDE, BUSUANGA, DINAGAT, HOMONHON, LEYTE, LUZON: NCR, MINDANAO: Agusan, Bukidnon (photos), Surigao del Norte, Surigao del Sur, PALAWAN, PANAY, ROMBLON, SIARGAO, SIBUYAN, TINAGO.', 'Lowland and medium elevation forests and regrowths on ultramafics. 700-800m (photos).'),
  ('7dff96db-3b1b-54bd-aefe-8964dd55242d', 'Hopea acuminata', 'Hopea', 'acuminata', 'Dipterocarpaceae', 'endemic', 'Hopea acuminata is a philippine endemic tree in Dipterocarpaceae. CDFP habitat record: Manggachapui. Common in semi-evergreen and evergreen forests. In most provinces in Luzon. 100-800m.', 'Leaves are simple, alternate, and usually leathery, with pinnate side veins; stipules and venation help separate dipterocarp genera.', 'The trunk is typically straight and resin-bearing; mature bark may become fissured or scaly, but color and texture must be checked for this species.', 'Small bisexual, five-parted flowers are borne in branched clusters; petals, stamens, and calyx lobes require close inspection.', 'The fruit is a one-seeded nut enclosed by a persistent calyx; enlarged wing-like calyx lobes aid wind dispersal and identification.', 'A single recalcitrant seed is enclosed in the nut and normally loses viability quickly if allowed to dry.', 'medium', 10, 30, 5, 12, 'slow', TRUE, TRUE, 'Vulnerable', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Endangered', 'Hopea acuminata', 'Endemic to the Philippines. BABUYAN ISLS, BASILAN, BOHOL, CALAYAN, LEYTE, LUZON: Aurora, Bataan, Cagayan, Camarines Sur, Isabela, Laguna, Sorsogon, MINDANAO: Cotabato, Davao, Misamis, Zamboanga, MINDORO, NEGROS, PANAY, SAMAR, SIBUYAN, SULU ARCHIPELAGO, TICAO.', 'Manggachapui. Common in semi-evergreen and evergreen forests. In most provinces in Luzon. 100-800m.'),
  ('52a9a295-f4e7-5fc5-bf70-b72efbd79472', 'Hopea philippinensis', 'Hopea', 'philippinensis', 'Dipterocarpaceae', 'endemic', 'Hopea philippinensis is a philippine endemic tree in Dipterocarpaceae. CDFP habitat record: Guisok-guisok. Primary evergreen forests on hills in aseasonal areas, often common. 0-500m.', 'Leaves are simple, alternate, and usually leathery, with pinnate side veins; stipules and venation help separate dipterocarp genera.', 'The trunk is typically straight and resin-bearing; mature bark may become fissured or scaly, but color and texture must be checked for this species.', 'Small bisexual, five-parted flowers are borne in branched clusters; petals, stamens, and calyx lobes require close inspection.', 'The fruit is a one-seeded nut enclosed by a persistent calyx; enlarged wing-like calyx lobes aid wind dispersal and identification.', 'A single recalcitrant seed is enclosed in the nut and normally loses viability quickly if allowed to dry.', 'medium', 10, 30, 5, 12, 'slow', TRUE, TRUE, 'Endangered', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Critically Endangered', 'Hopea philippinensis', 'Endemic to the Philippines. BASILAN, BILIRAN, BOHOL, CATANDUANES, HOMONHON, LEYTE, LUZON: Albay, Camarines, Camarines Sur, Laguna, Quezon, MINDANAO: Agusan, Agusan del Norte, Bukidnon (photos), Davao, Lanao, Surigao, Surigao del Sur, Zamboanga, Zamboanga del Norte (photos), NEGROS, PANAY, SAMAR, SULU ARCHIPELAGO.', 'Guisok-guisok. Primary evergreen forests on hills in aseasonal areas, often common. 0-500m.'),
  ('0d417ab2-ad1f-5965-a131-e560b7ae691b', 'Hopea foxworthyi', 'Hopea', 'foxworthyi', 'Dipterocarpaceae', 'endemic', 'Hopea foxworthyi is a philippine endemic tree in Dipterocarpaceae. CDFP habitat record: Locally common on red sticky volcanic soil along ridges, in seasonal semi-evergreen forest. Collections cited by Foxworthy and Merrill from islands other than Sibuyan belong to Hopea malibato. 600-700m.', 'Leaves are simple, alternate, and usually leathery, with pinnate side veins; stipules and venation help separate dipterocarp genera.', 'The trunk is typically straight and resin-bearing; mature bark may become fissured or scaly, but color and texture must be checked for this species.', 'Small bisexual, five-parted flowers are borne in branched clusters; petals, stamens, and calyx lobes require close inspection.', 'The fruit is a one-seeded nut enclosed by a persistent calyx; enlarged wing-like calyx lobes aid wind dispersal and identification.', 'A single recalcitrant seed is enclosed in the nut and normally loses viability quickly if allowed to dry.', 'medium', 10, 30, 5, 12, 'slow', TRUE, TRUE, 'Endangered', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Critically Endangered', 'Hopea foxworthyi', 'Endemic to the Philippines. SAMAR, SIBUYAN.', 'Locally common on red sticky volcanic soil along ridges, in seasonal semi-evergreen forest. Collections cited by Foxworthy and Merrill from islands other than Sibuyan belong to Hopea malibato. 600-700m.'),
  ('e08cbd05-69f7-5353-9894-91c3ed9275c3', 'Xanthostemon philippinensis', 'Xanthostemon', 'philippinensis', 'Myrtaceae', 'endemic', 'Xanthostemon philippinensis is a philippine endemic tree in Myrtaceae. CDFP habitat record: Lowland primary forests. 40m.', 'Leaves are simple, opposite, and leathery, with an intramarginal vein and fine oil glands typical of many Myrtaceae.', 'Bark is firm on young stems and becomes rough, fissured, or peeling with age; Tristaniopsis is especially noted for exfoliating bark.', 'Flowers have numerous conspicuous stamens; color and arrangement of the flower clusters are useful identification characters.', 'The dry capsule opens at maturity; the persistent calyx and capsule shape help confirm identity.', 'Several small seeds occur in each capsule and should be sown fresh after collection from a verified tree.', 'medium', 8, 25, 4, 12, 'moderate', TRUE, TRUE, 'Vulnerable', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Critically Endangered', 'Xanthostemon philippinensis', 'Endemic to the Philippines. LUZON: Aurora (photos), Camarines, Camarines Norte, SAMAR.', 'Lowland primary forests. 40m.'),
  ('2e69c3fe-ca94-5bdc-9c3e-abb8fc9f54a5', 'Lithocarpus luzoniensis', 'Lithocarpus', 'luzoniensis', 'Fagaceae', 'endemic', 'Lithocarpus luzoniensis is a philippine endemic tree in Fagaceae. CDFP habitat record: Mossy forests, rather common in the Cordillera Highlands of N Luzon. Fl. Jan-Jun; fr. Jul-Mar. 1500-2700m.', 'Leaves are alternate, simple, and leathery with pinnate veins; lower-surface texture and margin characters are useful in identification.', 'Mature trunks develop gray to brown, rough or fissured bark.', 'Tiny unisexual flowers occur in upright or spreading catkin-like spikes.', 'The fruit is an acorn-like nut partly enclosed by a woody cupule whose scales or rings are diagnostic.', 'A single large seed fills the nut and is generally best sown fresh.', 'large', 12, 35, 6, 16, 'slow', TRUE, TRUE, 'Near Threatened', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Other Threatened Species', 'Lithocarpus luzoniensis', 'Endemic to the Philippines. LUZON: Batangas, Benguet, Ifugao, Ilocos Sur, Laguna, Mountain Province, Nueva Vizcaya, Zambales.', 'Mossy forests, rather common in the Cordillera Highlands of N Luzon. Fl. Jan-Jun; fr. Jul-Mar. 1500-2700m.'),
  ('d2d6ccc2-22dc-504f-a535-66fad2f78c41', 'Dillenia monantha', 'Dillenia', 'monantha', 'Dilleniaceae', 'endemic', 'Dillenia monantha is a philippine endemic tree in Dilleniaceae. CDFP habitat record: Dry secondary forests and open grasslands at low elevation. 50m (photos).', 'Leaves are large, alternate, prominently parallel-veined, and usually toothed, with a rough or corrugated appearance.', 'Bark is gray-brown and becomes shallowly fissured or flaky on older stems.', 'Large flowers have five broad petals and many yellow stamens, making flowering trees conspicuous.', 'The rounded aggregate fruit is enclosed by enlarged, persistent sepals.', 'Numerous small seeds are embedded in the fruit pulp.', 'medium', 8, 20, 5, 12, 'moderate', TRUE, TRUE, 'Vulnerable', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Vulnerable', 'Dillenia monantha', 'Endemic to the Philippines. BUSUANGA, CULION, DUMARAN, PALAWAN, SEMIRARA (photos).', 'Dry secondary forests and open grasslands at low elevation. 50m (photos).'),
  ('c6ff18e9-eb2d-5b83-90ab-1e4f81509aec', 'Tristaniopsis decorticata', 'Tristaniopsis', 'decorticata', 'Myrtaceae', 'endemic', 'Tristaniopsis decorticata is a philippine endemic tree in Myrtaceae. CDFP habitat record: Primary forests, chiefly at low and medium elevation.', 'Leaves are simple, opposite, and leathery, with an intramarginal vein and fine oil glands typical of many Myrtaceae.', 'Bark is firm on young stems and becomes rough, fissured, or peeling with age; Tristaniopsis is especially noted for exfoliating bark.', 'Flowers have numerous conspicuous stamens; color and arrangement of the flower clusters are useful identification characters.', 'The dry capsule opens at maturity; the persistent calyx and capsule shape help confirm identity.', 'Several small seeds occur in each capsule and should be sown fresh after collection from a verified tree.', 'medium', 8, 25, 4, 12, 'moderate', TRUE, TRUE, 'Least Concern', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Other Threatened Species', 'Tristaniopsis decorticata', 'Endemic to the Philippines. DINAGAT, LUZON: Aurora, Bataan, Bulacan, Cagayan, Camarines, Ilocos Norte, Nueva Vizcaya (photos), Quezon, Rizal, MINDANAO: Agusan del Sur (photos), Davao, Surigao, Surigao del Norte, PALAWAN, POLILLO.', 'Primary forests, chiefly at low and medium elevation.'),
  ('dfa1e250-9158-5de4-a08d-20bac0dce9e5', 'Syzygium polycephaloides', 'Syzygium', 'polycephaloides', 'Myrtaceae', 'native', 'Syzygium polycephaloides is a philippine native tree in Myrtaceae. CDFP habitat record: Common in primary forests at low and medium elevation.', 'Leaves are simple, opposite, and leathery, with an intramarginal vein and fine oil glands typical of many Myrtaceae.', 'Bark is firm on young stems and becomes rough, fissured, or peeling with age; Tristaniopsis is especially noted for exfoliating bark.', 'Flowers have numerous conspicuous stamens; color and arrangement of the flower clusters are useful identification characters.', 'The fruit is a fleshy berry, often ripening from pale colors to red or purple; shape and clustering vary by species.', 'One or a few relatively large seeds are enclosed in the berry; use fresh, correctly identified fruit for propagation.', 'medium', 8, 25, 4, 12, 'moderate', TRUE, TRUE, NULL, 'No global category stated in the CDFP record consulted', 'Syzygium polycephaloides', 'Lesser Sunda Isls, Philippines, Sulawesi. CATANDUANES, LEYTE, LUZON: Albay, Bulacan, Cagayan, Camarines Norte, Camarines Sur, Ifugao, Isabela, Laguna, Quezon, Sorsogon, MASBATE, MINDANAO: Surigao del Norte, MINDORO, PALAUI, PANAY (photos), SAMAR.', 'Common in primary forests at low and medium elevation.'),
  ('b0c418c8-d0cf-5ae2-be2b-7ce15c69f073', 'Syzygium calubcob', 'Syzygium', 'calubcob', 'Myrtaceae', 'native', 'Syzygium calubcob is a philippine native tree in Myrtaceae. CDFP habitat record: Batan Isls and Luzon to Palawan and Mindanao. Common and widely distributed in thickets and forests at low and medium elevation.', 'Leaves are simple, opposite, and leathery, with an intramarginal vein and fine oil glands typical of many Myrtaceae.', 'Bark is firm on young stems and becomes rough, fissured, or peeling with age; Tristaniopsis is especially noted for exfoliating bark.', 'Flowers have numerous conspicuous stamens; color and arrangement of the flower clusters are useful identification characters.', 'The fruit is a fleshy berry, often ripening from pale colors to red or purple; shape and clustering vary by species.', 'One or a few relatively large seeds are enclosed in the berry; use fresh, correctly identified fruit for propagation.', 'medium', 8, 25, 4, 12, 'moderate', TRUE, TRUE, NULL, 'No global category stated in the CDFP record consulted', 'Syzygium calubcob', 'Philippines, Sulawesi. BATAN, BATANES, CALAYAN, CATANDUANES, GUIMARAS, ?LEYTE, LUZON: Benguet, Bulacan, Camarines, Camarines Sur, Cavite (photos), Ilocos Sur, Isabela, La Union, Laguna, NCR, Nueva Vizcaya, Pampanga, Pangasinan, Quezon, Rizal, Tarlac, MINDANAO: Agusan del Norte, MINDORO, NEGROS, PALAWAN, POLO, SABTANG.', 'Batan Isls and Luzon to Palawan and Mindanao. Common and widely distributed in thickets and forests at low and medium elevation.'),
  ('4bef4af4-ed05-5bcd-9446-bd12afd11631', 'Syzygium tripinnatum', 'Syzygium', 'tripinnatum', 'Myrtaceae', 'native', 'Syzygium tripinnatum is a philippine native tree in Myrtaceae. CDFP habitat record: In Luzon from Cagayan to Sorsogon. Primary forests at sea level and low and medium elevation. 0-225m (photos).', 'Leaves are simple, opposite, and leathery, with an intramarginal vein and fine oil glands typical of many Myrtaceae.', 'Bark is firm on young stems and becomes rough, fissured, or peeling with age; Tristaniopsis is especially noted for exfoliating bark.', 'Flowers have numerous conspicuous stamens; color and arrangement of the flower clusters are useful identification characters.', 'The fruit is a fleshy berry, often ripening from pale colors to red or purple; shape and clustering vary by species.', 'One or a few relatively large seeds are enclosed in the berry; use fresh, correctly identified fruit for propagation.', 'medium', 8, 25, 4, 12, 'moderate', TRUE, TRUE, NULL, 'No global category stated in the CDFP record consulted', 'Syzygium tripinnatum', 'Philippines, Taiwan. LUZON: Albay, Apayao, Aurora (photos), Bataan, Bulacan, Cagayan, Camarines, Laguna, Nueva Ecija, Pangasinan, Quezon, Rizal, Sorsogon, MINDANAO: Davao del Norte, Lanao, MINDORO, NEGROS, PANAY, SAMAR.', 'In Luzon from Cagayan to Sorsogon. Primary forests at sea level and low and medium elevation. 0-225m (photos).'),
  ('971e6336-9e58-5f13-ba58-025545a6deee', 'Terminalia microcarpa', 'Terminalia', 'microcarpa', 'Combretaceae', 'native', 'Terminalia microcarpa is a philippine native tree in Combretaceae. CDFP habitat record: In all or most provinces in the Philippines. A usually tall tree common in both primary evergreen and in seasonal deciduous forests. 0-830m.', 'Simple leaves are alternate but often crowded near twig ends; shape, base glands, and lower-surface hairs help distinguish species.', 'Older bark is gray to brown and commonly becomes fissured or scaly.', 'Small flowers lacking showy petals are grouped in spikes or short panicles.', 'The fruit is a fleshy to firm, often flattened or ridged drupe; mature color and cross-section are useful characters.', 'A single seed is protected by the hard inner layer of the fruit.', 'large', 15, 35, 7, 18, 'moderate', TRUE, TRUE, 'Least Concern', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Terminalia microcarpa', 'Australia, Bismarck Arch, Borneo, Java, Lesser Sunda Isls, Moluccas, New Guinea, Philippines, Solomon Isls, Sulawesi, Sumatra. CATANDUANES, GUIMARAS, LUZON: Abra (photos), Albay, Aurora, Bataan, Batangas, Bulacan, Cagayan, Camarines Norte, Camarines Sur, Isabela (photos), Laguna, Nueva Ecija, Pangasinan, Quezon, Rizal, Sorsogon, Zambales, MARINDUQUE, MASBATE, MINDANAO: Agusan del Norte, Surigao del Sur, Zamboanga, MINDORO, NEGROS, PALAWAN, PANAY (photos), SAMAR, SIBUYAN.', 'In all or most provinces in the Philippines. A usually tall tree common in both primary evergreen and in seasonal deciduous forests. 0-830m.'),
  ('38a9b34e-3e83-52f2-a83e-4fe7ade43495', 'Terminalia pellucida', 'Terminalia', 'pellucida', 'Combretaceae', 'native', 'Terminalia pellucida is a philippine native tree in Combretaceae. CDFP habitat record: Forests at low elevation.', 'Simple leaves are alternate but often crowded near twig ends; shape, base glands, and lower-surface hairs help distinguish species.', 'Older bark is gray to brown and commonly becomes fissured or scaly.', 'Small flowers lacking showy petals are grouped in spikes or short panicles.', 'The fruit is a fleshy to firm, often flattened or ridged drupe; mature color and cross-section are useful characters.', 'A single seed is protected by the hard inner layer of the fruit.', 'large', 15, 35, 7, 18, 'moderate', TRUE, TRUE, 'Least Concern', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Terminalia pellucida', 'Moluccas, Philippines. GOLO, LUZON: Cagayan, Ilocos Norte, Pampanga, Pangasinan, Quezon, Rizal, Tarlac, Zambales, MINDANAO: Davao, MINDORO, PALAWAN, PANAY, SULU ARCHIPELAGO.', 'Forests at low elevation.'),
  ('d884340e-f82a-508e-b7a9-ad99f6518afa', 'Albizia acle', 'Albizia', 'acle', 'Fabaceae', 'native', 'Albizia acle is a philippine native tree in Fabaceae. CDFP habitat record: Throughout the Philippines. Lowland forests, humid forests. Fl. Mar-Apr; fr. Sep-Oct, Jan-Feb. Common name: Akle. 0-150m.', 'Leaves are twice pinnate, with many small leaflets; gland position on the leaf axis helps identification.', 'Bark is gray-brown and becomes rough or fissured on mature trunks.', 'Small flowers are massed in heads, with projecting stamens producing a brush-like appearance.', 'The fruit is a flattened, dry legume that becomes brown at maturity.', 'Several hard, flattened seeds lie in a row inside the pod.', 'large', 15, 30, 8, 20, 'moderate', TRUE, TRUE, 'Near Threatened', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Albizia acle', 'Philippines, Sulawesi. BALABAC, BILIRAN, LUZON: Albay, Bataan, Bulacan, Ifugao, Laguna, NCR, Quezon, Rizal, Tarlac, Zambales, MASBATE, NEGROS, PALAWAN, TABLAS.', 'Throughout the Philippines. Lowland forests, humid forests. Fl. Mar-Apr; fr. Sep-Oct, Jan-Feb. Common name: Akle. 0-150m.'),
  ('1008e9d2-2200-5465-b660-cc2f19de3ae9', 'Cinnamomum cebuense', 'Cinnamomum', 'cebuense', 'Lauraceae', 'endemic', 'Cinnamomum cebuense is a philippine endemic tree in Lauraceae. CDFP habitat record: Mountain forest. 800m.', 'Leaves are aromatic when crushed and usually show three strong veins arising near the base; arrangement and lower-surface characters separate the genera.', 'Inner bark and twigs are aromatic; avoid harvesting bark from wild trees, especially threatened species.', 'Small pale flowers occur in clustered inflorescences and have the typical laurel-family floral structure.', 'The fruit is a one-seeded drupe seated on a persistent cup-like or shallow receptacle.', 'The single seed is enclosed by the fleshy drupe and is best handled fresh.', 'medium', 8, 25, 4, 12, 'moderate', TRUE, TRUE, 'Endangered', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Endangered', 'Cinnamomum cebuense', 'Endemic to the Philippines. CEBU.', 'Mountain forest. 800m.'),
  ('8a450899-6d83-5a03-bf8a-b329fe9036d9', 'Cinnamomum burmanni', 'Cinnamomum', 'burmanni', 'Lauraceae', 'native', 'Cinnamomum burmanni is a philippine native tree in Lauraceae. CDFP habitat record: Although the ''typical'' form was mentioned by Merrill (1923) as an introduced but rarely cultivated species, wild forms formerly known as Cinnamomum mindanaense are known to occur in Jolo (Mt Dajo), Mindanao: Zamboanga, Davao (Mt Apo), and Surigao. In low and medium elevation thickets and forests. (?-)1500m. The submitted name Cinnamomum mindanaense is retained as an audit alias.', 'Leaves are aromatic when crushed and usually show three strong veins arising near the base; arrangement and lower-surface characters separate the genera.', 'Inner bark and twigs are aromatic; avoid harvesting bark from wild trees, especially threatened species.', 'Small pale flowers occur in clustered inflorescences and have the typical laurel-family floral structure.', 'The fruit is a one-seeded drupe seated on a persistent cup-like or shallow receptacle.', 'The single seed is enclosed by the fleshy drupe and is best handled fresh.', 'medium', 8, 25, 4, 12, 'moderate', TRUE, TRUE, 'Least Concern', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Cinnamomum mindanaense', 'Borneo, China, Hong Kong, Indian Ocean, Indochina, Japan, Java, Lesser Sunda Isls, Philippines, Sulawesi, Sumatra. CEBU (photos), JOLO, MINDANAO: Davao del Sur, Misamis Occidental, Surigao, Zamboanga, Zamboanga del Sur, SAMAR, SIBUYAN, SULU ARCHIPELAGO.', 'Although the ''typical'' form was mentioned by Merrill (1923) as an introduced but rarely cultivated species, wild forms formerly known as Cinnamomum mindanaense are known to occur in Jolo (Mt Dajo), Mindanao: Zamboanga, Davao (Mt Apo), and Surigao. In low and medium elevation thickets and forests. (?-)1500m.'),
  ('bc0788f7-2325-51bb-8b8a-5fc09b93e576', 'Petersianthus quadrialatus', 'Petersianthus', 'quadrialatus', 'Lecythidaceae', 'endemic', 'Petersianthus quadrialatus is a philippine endemic tree in Lecythidaceae. CDFP habitat record: Habitat details were not stated in the checklist record consulted.', 'Leaves are simple, alternate, and clustered toward twig ends, with a broad blade and prominent pinnate veins.', 'A mature tree has a massive straight bole with brown, fissured bark and supporting buttresses.', 'Small flowers are borne in branched clusters; the numerous stamens are characteristic of the family.', 'The dry fruit develops conspicuous longitudinal wings.', 'Seeds are contained within the winged dry fruit and should be collected only from verified trees.', 'large', 25, 55, 10, 22, 'moderate', TRUE, TRUE, 'Near Threatened', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Petersianthus quadrialatus', 'Endemic to the Philippines. DINAGAT, LEYTE (photos), LUZON: Laguna, Sorsogon, MASBATE, MINDANAO: Agusan, Surigao, Surigao del Sur (photos), SAMAR.', 'Habitat details were not stated in the checklist record consulted.'),
  ('21e0c2e8-544a-5dd7-ad7d-b77e2356e73e', 'Lithocarpus solerianus', 'Lithocarpus', 'solerianus', 'Fagaceae', 'endemic', 'Lithocarpus solerianus is a philippine endemic tree in Fagaceae. CDFP habitat record: Forests. Fl. Aug-May; fr. Apr-Oct. 400m (photos) to 700-1200m.', 'Leaves are alternate, simple, and leathery with pinnate veins; lower-surface texture and margin characters are useful in identification.', 'Mature trunks develop gray to brown, rough or fissured bark.', 'Tiny unisexual flowers occur in upright or spreading catkin-like spikes.', 'The fruit is an acorn-like nut partly enclosed by a woody cupule whose scales or rings are diagnostic.', 'A single large seed fills the nut and is generally best sown fresh.', 'large', 12, 35, 6, 16, 'slow', TRUE, TRUE, 'Least Concern', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Lithocarpus solerianus', 'Endemic to the Philippines. LUZON: Abra, Bataan, Batangas, Benguet, Bulacan, Ilocos Norte, Ilocos Sur, Laguna, Mountain Province, NCR, Quezon, Rizal, Zambales, MINDANAO: Agusan, Agusan del Norte, Davao, Davao del Sur, Misamis Occidental, Surigao del Norte, Zamboanga del Norte (photos), MINDORO, POLILLO, SAMAR, SIBUYAN.', 'Forests. Fl. Aug-May; fr. Apr-Oct. 400m (photos) to 700-1200m.'),
  ('88c6df94-8f7f-5e3a-8c2f-5310573af5f9', 'Ficus odorata', 'Ficus', 'odorata', 'Moraceae', 'endemic', 'Ficus odorata is a philippine endemic tree in Moraceae. CDFP habitat record: Lowland forests, often in secondary growths, near streams, and on rocks. Leaves aromatic on drying. 100-500m (photos).', 'Leaves are simple and alternate; stipule scars, venation, surface texture, and latex are useful identification features.', 'Bark is generally pale gray to brown; cuts exude white latex.', 'Minute male and female flowers are enclosed inside the fig structure and are not externally showy.', 'The fig is a fleshy syconium borne on twigs or older wood depending on species; color changes as it ripens.', 'Numerous minute seeds develop inside ripe figs and are dispersed mainly by animals.', 'large', 10, 30, 8, 22, 'fast', TRUE, TRUE, 'Least Concern', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Ficus odorata', 'Endemic to the Philippines. BATANES, BOHOL, CEBU (photos), LEYTE, LUZON: Bataan, Bulacan, Laguna, Pampanga (photos), Quezon (photos), Rizal, Zambales, MINDANAO: Agusan del Norte, Bukidnon, Cotabato, Davao del Sur, Lanao del Norte, NEGROS, PANAY, POLILLO, SAMAR.', 'Lowland forests, often in secondary growths, near streams, and on rocks. Leaves aromatic on drying. 100-500m (photos).'),
  ('cbd86590-c475-5269-b27d-c5a6e19aaa82', 'Ficus variegata', 'Ficus', 'variegata', 'Moraceae', 'native', 'Ficus variegata is a philippine native tree in Moraceae. CDFP habitat record: In Malesia throughout the region; forest and secondary growth; often in villages and gardens. 0-1200m.', 'Leaves are simple and alternate; stipule scars, venation, surface texture, and latex are useful identification features.', 'Bark is generally pale gray to brown; cuts exude white latex.', 'Minute male and female flowers are enclosed inside the fig structure and are not externally showy.', 'The fig is a fleshy syconium borne on twigs or older wood depending on species; color changes as it ripens.', 'Numerous minute seeds develop inside ripe figs and are dispersed mainly by animals.', 'large', 10, 30, 8, 22, 'fast', TRUE, TRUE, 'Least Concern', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Ficus variegata', 'Andaman Isls, Australia, China, India, Indochina, Myanmar, Philippines, Ryukyu Isls, Solomon Isls, Taiwan, Thailand. BASILAN, BOHOL, BUSUANGA, CAMIGUIN, CATANDUANES, CEBU, HOMONHON, LAGEN, LEYTE, LUZON: Abra, Albay, Apayao (photos), Bataan, Benguet, Cagayan, Camarines, Camarines Norte, Ifugao, Ilocos Norte, Ilocos Sur, Isabela, Laguna, Nueva Ecija, Pampanga, Quezon, Rizal, Sorsogon, Zambales, MARINDUQUE, MINDANAO: Agusan del Norte, Bukidnon (photos), Davao Oriental, Davao del Norte, Davao del Sur, Misamis Oriental (photos), Zamboanga, Zamboanga del Sur, MINDORO, NEGROS, PALAWAN, PANAY, POLILLO, SAMAR, SIBUYAN.', 'In Malesia throughout the region; forest and secondary growth; often in villages and gardens. 0-1200m.'),
  ('662e5d74-a436-5036-ac73-349d10cb498d', 'Aglaia edulis', 'Aglaia', 'edulis', 'Meliaceae', 'native', 'Aglaia edulis is a philippine native tree in Meliaceae. CDFP habitat record: Widespread in the Philippines. 0-1670m.', 'Leaves are alternate and pinnate, with glossy leaflets; leaflet number, scales or hairs, and venation aid identification.', 'Bark is gray to brown and may be smooth or shallowly fissured with age.', 'Very small, usually pale flowers are arranged in branched panicles.', 'The fruit is a berry-like or capsular structure whose color and opening pattern vary among Aglaia species.', 'One or more seeds may carry a fleshy aril attractive to wildlife.', 'medium', 8, 25, 4, 12, 'moderate', TRUE, TRUE, 'Near Threatened', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Aglaia edulis', 'Bhutan, Borneo, Cambodia, China, India, Java, Lesser Sunda Isls, Malay Peninsula, Moluccas, Myanmar, Nicobar Isls, Philippines, Sulawesi, Sumatra, Thailand, Vietnam. BASILAN, BURIAS, LEYTE, LUZON: Bataan, Cagayan, Ilocos Norte, Isabela (photos), Laguna, Nueva Ecija, Quezon, Rizal, Sorsogon, MASBATE, MINDANAO: Agusan del Norte, Cotabato, Davao, Davao del Norte, Davao del Sur, Zamboanga, MINDORO, NEGROS, PALAWAN, SAMAR.', 'Widespread in the Philippines. 0-1670m.'),
  ('bee42eff-136e-5cf7-8ed1-18f5514df96b', 'Actinodaphne multiflora', 'Actinodaphne', 'multiflora', 'Lauraceae', 'native', 'Actinodaphne multiflora is a philippine native tree in Lauraceae. CDFP habitat record: Primary forests at low and medium elevation. 600-1860m. The submitted name Neolitsea vidalii is retained as an audit alias. CDFP documents Philippine native records under the synonym Neolitsea vidalii; POWO''s current range presentation is narrower, so the Philippine occurrence is flagged for future herbarium review.', 'Leaves are aromatic when crushed and usually show three strong veins arising near the base; arrangement and lower-surface characters separate the genera.', 'Inner bark and twigs are aromatic; avoid harvesting bark from wild trees, especially threatened species.', 'Small pale flowers occur in clustered inflorescences and have the typical laurel-family floral structure.', 'The fruit is a one-seeded drupe seated on a persistent cup-like or shallow receptacle.', 'The single seed is enclosed by the fleshy drupe and is best handled fresh.', 'medium', 8, 25, 4, 12, 'moderate', TRUE, TRUE, 'Least Concern', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Neolitsea vidalii', 'Lesser Sunda Isls, New Guinea, Philippines, Solomon Isls, Thailand. BASILAN, BILIRAN, GUIMARAS, LUZON: ?Aurora, Bataan, Benguet, Cagayan, Camarines, Camarines Sur, Laguna, Quezon, Rizal, Sorsogon, MARINDUQUE, MASBATE, MINDANAO: Agusan del Norte, Cotabato, Davao del Sur, Misamis Occidental, South Cotabato, MINDORO, NEGROS, PALAWAN, SIBUYAN, SULU ARCHIPELAGO.', 'Primary forests at low and medium elevation. 600-1860m.'),
  ('24310924-e720-5eb6-bef8-861c6a22e886', 'Aglaia cumingiana', 'Aglaia', 'cumingiana', 'Meliaceae', 'native', 'Aglaia cumingiana is a philippine native tree in Meliaceae. CDFP habitat record: In primary, secondary and gallery forests, along seashore, on sandy soil. 0-1330m.', 'Leaves are alternate and pinnate, with glossy leaflets; leaflet number, scales or hairs, and venation aid identification.', 'Bark is gray to brown and may be smooth or shallowly fissured with age.', 'Very small, usually pale flowers are arranged in branched panicles.', 'The fruit is a berry-like or capsular structure whose color and opening pattern vary among Aglaia species.', 'One or more seeds may carry a fleshy aril attractive to wildlife.', 'medium', 8, 25, 4, 12, 'moderate', TRUE, TRUE, 'Vulnerable', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Aglaia cumingiana', 'Borneo, Philippines. BANCALAN, BOHOL, CEBU, GUIMARAS, LUZON: Albay, Benguet, Bulacan, Cagayan, Ilocos Norte, Isabela, Laguna, Nueva Ecija, Nueva Vizcaya, Pangasinan, Rizal, MINDANAO: Davao, Davao del Sur, Zamboanga, Zamboanga del Sur, MINDORO, NEGROS, PALAWAN, PANAY, TAWI-TAWI.', 'In primary, secondary and gallery forests, along seashore, on sandy soil. 0-1330m.'),
  ('4b820c00-6f29-503b-9d71-4da74808e24b', 'Taxotrophis ilicifolia', 'Taxotrophis', 'ilicifolia', 'Moraceae', 'native', 'Taxotrophis ilicifolia is a philippine native tree in Moraceae. CDFP habitat record: Dry thickets and thin forests at low elevation. Also on limestone. 0-1100m.', 'Leaves are simple and alternate, often stiff with toothed or spiny margins; latex may be present.', 'Bark is gray-brown and relatively thin on smaller stems.', 'Small unisexual flowers occur in compact axillary clusters.', 'The small fleshy drupe ripens to a contrasting color and is used by wildlife.', 'A single seed is enclosed by the drupe.', 'small', 4, 15, 3, 8, 'moderate', TRUE, TRUE, 'Least Concern', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Taxotrophis ilicifolia', 'Bangladesh, Borneo, China, Indochina, Lesser Sunda Isls, Malay Peninsula, Moluccas, Myanmar, New Guinea, Philippines, Sulawesi, Thailand. BASILAN, CEBU, CORON, DANJUGAN (photos), LUZON: Bataan, Cagayan, Camarines, Camarines Sur, Laguna, Quezon, Rizal, MARINDUQUE, MINDANAO: Misamis Oriental (photos), MINDORO, NEGROS, PALAWAN, PANAY.', 'Dry thickets and thin forests at low elevation. Also on limestone. 0-1100m.'),
  ('d67c4121-8a01-529f-a79a-5fbba93448f7', 'Mangifera altissima', 'Mangifera', 'altissima', 'Anacardiaceae', 'endemic', 'Mangifera altissima is a philippine endemic tree in Anacardiaceae. CDFP habitat record: Chiefly in lowland primary forests whether inland or sometimes coastal. Common. 0-540m.', 'Leaves are alternate, simple, leathery, and lance-shaped, with many fine side veins; young flushes may be reddish.', 'Bark is gray-brown and becomes rough or fissured; damaged tissue may release irritating resin.', 'Numerous small flowers are borne in large terminal panicles.', 'The fruit is a fleshy, mango-like drupe; size, skin color, fibers, and scent differ by species.', 'One large flattened seed is enclosed in a fibrous or woody stone.', 'large', 15, 40, 8, 20, 'moderate', TRUE, TRUE, 'Data Deficient', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Vulnerable', 'Mangifera altissima', 'Endemic to the Philippines. ALABAT, LAGEN, LUZON: Aurora, Bataan, Bulacan, Cagayan, Camarines, Camarines Sur, Ilocos Sur, Isabela, Laguna, NCR, Nueva Ecija, Quezon, Rizal, Tarlac, Zambales, MINDANAO: Lanao, Zamboanga del Sur, MINDORO, PALAWAN, SIBUYAN.', 'Chiefly in lowland primary forests whether inland or sometimes coastal. Common. 0-540m.'),
  ('6b78842d-b9ff-5dee-8aac-ea402b8a0aa1', 'Mangifera caesia', 'Mangifera', 'caesia', 'Anacardiaceae', 'native', 'Mangifera caesia is a philippine native tree in Anacardiaceae. CDFP habitat record: Primary forests, swamp or periodically inundated areas along rivers. Also in semicultivated state. 0-450m.', 'Leaves are alternate, simple, leathery, and lance-shaped, with many fine side veins; young flushes may be reddish.', 'Bark is gray-brown and becomes rough or fissured; damaged tissue may release irritating resin.', 'Numerous small flowers are borne in large terminal panicles.', 'The fruit is a fleshy, mango-like drupe; size, skin color, fibers, and scent differ by species.', 'One large flattened seed is enclosed in a fibrous or woody stone.', 'large', 15, 40, 8, 20, 'moderate', TRUE, TRUE, 'Near Threatened', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Mangifera caesia', 'Borneo, Java, Malay Peninsula, Philippines, Sumatra. BASILAN, MINDANAO: Agusan, Agusan del Norte, Bukidnon, Davao del Norte, Misamis, Surigao, Surigao del Norte, Zamboanga, Zamboanga del Norte, PALAWAN.', 'Primary forests, swamp or periodically inundated areas along rivers. Also in semicultivated state. 0-450m.'),
  ('1e27e5ac-7b67-54f1-baab-be203da080d6', 'Garcinia rubra', 'Garcinia', 'rubra', 'Clusiaceae', 'endemic', 'Garcinia rubra is a philippine endemic tree in Clusiaceae. CDFP habitat record: Primary forests at sea level and low elevation.', 'Leaves are opposite, simple, entire, and leathery, with close parallel side veins.', 'Cut bark and twigs produce yellowish latex, an important Garcinia field character.', 'Small thick-petaled flowers may be male or female and occur singly or in short clusters.', 'The fruit is a fleshy berry with a persistent calyx; mature color and surface texture help distinguish species.', 'Several large seeds are usually surrounded by pulp.', 'medium', 8, 25, 4, 12, 'slow', TRUE, TRUE, 'Near Threatened', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Garcinia rubra', 'Endemic to the Philippines. BALABAC, BASILAN, CAMIGUIN, CATANDUANES, CEBU, LEYTE, LUZON: Albay, Apayao, Aurora, Cagayan, Camarines, Isabela, Laguna, Quezon, Rizal, Sorsogon, MATINLOC, MINDANAO: Agusan del Norte, Bukidnon, Cotabato (photos), Davao del Norte, Lanao del Sur, Zamboanga, Zamboanga del Norte, MINDORO, NEGROS (photos), PALAWAN, SAMAR, SULU ARCHIPELAGO, TURTLE IS.', 'Primary forests at sea level and low elevation.'),
  ('fee2f14f-fdd0-572f-9109-c90fed8c6b27', 'Garcinia nervosa', 'Garcinia', 'nervosa', 'Clusiaceae', 'native', 'Garcinia nervosa is a philippine native tree in Clusiaceae. CDFP habitat record: Primary forests at low elevation.', 'Leaves are opposite, simple, entire, and leathery, with close parallel side veins.', 'Cut bark and twigs produce yellowish latex, an important Garcinia field character.', 'Small thick-petaled flowers may be male or female and occur singly or in short clusters.', 'The fruit is a fleshy berry with a persistent calyx; mature color and surface texture help distinguish species.', 'Several large seeds are usually surrounded by pulp.', 'medium', 8, 25, 4, 12, 'slow', TRUE, TRUE, 'Least Concern', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Garcinia nervosa', 'Malay Peninsula, Philippines, Singapore, Sumatra. LUZON: Camarines, Quezon, PALAWAN, SAMAR.', 'Primary forests at low elevation.'),
  ('ac6251fe-321a-59d1-b3d7-e956d75f3671', 'Octomeles sumatrana', 'Octomeles', 'sumatrana', 'Tetramelaceae', 'native', 'Octomeles sumatrana is a philippine native tree in Tetramelaceae. CDFP habitat record: 0-800m.', 'Leaves are large, simple, alternate, and broadly heart-shaped with radiating basal veins.', 'The tall bole is gray and becomes shallowly fissured, often with substantial buttresses at the base.', 'Trees are male or female; the very small flowers occur in separate clustered inflorescences.', 'Female trees bear many small dry capsules.', 'Each capsule releases numerous dust-like seeds suited to wind dispersal.', 'large', 25, 60, 10, 25, 'fast', TRUE, TRUE, 'Least Concern', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Octomeles sumatrana', 'Borneo, Moluccas, New Guinea, Philippines, Solomon Isls, Sulawesi, Sumatra. LUZON: Apayao (photos), Isabela (photos), MINDANAO: Bukidnon (photos), Davao del Norte, Lanao del Norte (photos), Misamis Oriental (photos), MINDORO (photos), PALAWAN.', '0-800m.'),
  ('14a32511-dfa0-5910-9a0c-a21855f37d6a', 'Duabanga moluccana', 'Duabanga', 'moluccana', 'Lythraceae', 'native', 'Duabanga moluccana is a philippine native tree in Lythraceae. CDFP habitat record: Widespread in the Philippines. 0-1200m.', 'Leaves are large, simple, opposite, and entire, with many prominent parallel side veins.', 'Bark is gray-brown and may flake in irregular patches on older trees.', 'Large pale flowers carry numerous stamens and are borne near branch ends.', 'The fruit is a persistent-calyx capsule that opens to release many seeds.', 'Numerous small, lightweight seeds occur in each capsule.', 'large', 18, 40, 8, 20, 'fast', TRUE, TRUE, 'Least Concern', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Duabanga moluccana', 'Borneo, Java, Lesser Sunda Isls, Moluccas, New Guinea, Philippines, Sulawesi. BALABAC, CAMIGUIN (photos), CATANDUANES, LEYTE, LUZON: Abra, Apayao, Aurora, Bulacan, Camarines Sur, Cavite, Ilocos Norte, Ilocos Sur, Isabela, Laguna, Quezon, Rizal, Sorsogon, MASBATE, MINDANAO: Agusan del Norte, Bukidnon (photos), Cotabato, Davao, Davao Oriental, Davao del Sur, Misamis Occidental, South Cotabato, Sultan Kudarat (photos), Zamboanga, Zamboanga del Sur, MINDORO, NEGROS (photos), PALAWAN, PANAY (photos).', 'Widespread in the Philippines. 0-1200m.'),
  ('322e6daf-a597-5b65-a828-54d1420fccc3', 'Hopea basilanica', 'Hopea', 'basilanica', 'Dipterocarpaceae', 'endemic', 'Hopea basilanica is a philippine endemic tree in Dipterocarpaceae. CDFP habitat record: Primary lowland forests on undulating hills. 0-70m. It replaces the submitted Parashorea densiflora, whose documented native range does not include the Philippines.', 'Leaves are simple, alternate, and usually leathery, with pinnate side veins; stipules and venation help separate dipterocarp genera.', 'The trunk is typically straight and resin-bearing; mature bark may become fissured or scaly, but color and texture must be checked for this species.', 'Small bisexual, five-parted flowers are borne in branched clusters; petals, stamens, and calyx lobes require close inspection.', 'The fruit is a one-seeded nut enclosed by a persistent calyx; enlarged wing-like calyx lobes aid wind dispersal and identification.', 'A single recalcitrant seed is enclosed in the nut and normally loses viability quickly if allowed to dry.', 'medium', 10, 30, 5, 12, 'slow', TRUE, TRUE, 'Critically Endangered', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Critically Endangered', 'Parashorea densiflora', 'Endemic to the Philippines. BASILAN, MINDANAO: Zamboanga, SIBUTU, SULU ARCHIPELAGO.', 'Primary lowland forests on undulating hills. 0-70m.'),
  ('e555419e-7546-5e21-a6b3-0ab368bcdd5d', 'Shorea seminis', 'Shorea', 'seminis', 'Dipterocarpaceae', 'native', 'Shorea seminis is a philippine native tree in Dipterocarpaceae. CDFP habitat record: Reported for the Philippines by Ashton (1982). Merrill (1923) also cites Malay Peninsula and Banka. Primary lowland forests. 106m (photos).', 'Leaves are simple, alternate, and usually leathery, with pinnate side veins; stipules and venation help separate dipterocarp genera.', 'The trunk is typically straight and resin-bearing; mature bark may become fissured or scaly, but color and texture must be checked for this species.', 'Small bisexual, five-parted flowers are borne in branched clusters; petals, stamens, and calyx lobes require close inspection.', 'The fruit is a one-seeded nut enclosed by a persistent calyx; enlarged wing-like calyx lobes aid wind dispersal and identification.', 'A single recalcitrant seed is enclosed in the nut and normally loses viability quickly if allowed to dry.', 'large', 18, 45, 7, 18, 'slow', TRUE, TRUE, 'Least Concern', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Vulnerable', 'Shorea seminis', 'Borneo, Philippines. MINDANAO: Zamboanga Sibugay (photos).', 'Reported for the Philippines by Ashton (1982). Merrill (1923) also cites Malay Peninsula and Banka. Primary lowland forests. 106m (photos).'),
  ('1381c602-9109-5cf7-9b96-3c519cd07bdf', 'Hopea cagayanensis', 'Hopea', 'cagayanensis', 'Dipterocarpaceae', 'endemic', 'Hopea cagayanensis is a philippine endemic tree in Dipterocarpaceae. CDFP habitat record: Primary lowland semi-evergreen forests. 0-330m. It replaces the submitted Shorea ciliata, whose documented native range does not include the Philippines.', 'Leaves are simple, alternate, and usually leathery, with pinnate side veins; stipules and venation help separate dipterocarp genera.', 'The trunk is typically straight and resin-bearing; mature bark may become fissured or scaly, but color and texture must be checked for this species.', 'Small bisexual, five-parted flowers are borne in branched clusters; petals, stamens, and calyx lobes require close inspection.', 'The fruit is a one-seeded nut enclosed by a persistent calyx; enlarged wing-like calyx lobes aid wind dispersal and identification.', 'A single recalcitrant seed is enclosed in the nut and normally loses viability quickly if allowed to dry.', 'medium', 10, 30, 5, 12, 'slow', TRUE, TRUE, 'Endangered', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Critically Endangered', 'Shorea ciliata', 'Endemic to the Philippines. LUZON: Apayao, Cagayan, Ilocos; MINDANAO: Davao del Sur; SAMAR.', 'Primary lowland semi-evergreen forests. 0-330m.'),
  ('98984593-d382-5bf1-8007-a268f4de568a', 'Shorea falciferoides', 'Shorea', 'falciferoides', 'Dipterocarpaceae', 'native', 'Shorea falciferoides is a philippine native tree in Dipterocarpaceae. CDFP habitat record: 0-1000m.', 'Leaves are simple, alternate, and usually leathery, with pinnate side veins; stipules and venation help separate dipterocarp genera.', 'The trunk is typically straight and resin-bearing; mature bark may become fissured or scaly, but color and texture must be checked for this species.', 'Small bisexual, five-parted flowers are borne in branched clusters; petals, stamens, and calyx lobes require close inspection.', 'The fruit is a one-seeded nut enclosed by a persistent calyx; enlarged wing-like calyx lobes aid wind dispersal and identification.', 'A single recalcitrant seed is enclosed in the nut and normally loses viability quickly if allowed to dry.', 'large', 18, 45, 7, 18, 'slow', TRUE, TRUE, 'Vulnerable', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Vulnerable', 'Shorea falciferoides', 'Borneo, Philippines, Sumatra. BASILAN, CEBU, DINAGAT, LEYTE, LUZON: Albay, Bulacan, Camarines, Camarines Norte, Isabela (photos), Laguna, Nueva Ecija, Pangasinan, Quezon, Zambales, MINDANAO: Agusan, Davao, Surigao, Surigao del Sur (photos), Zamboanga, MINDORO, SAMAR, SIBUYAN.', '0-1000m.'),
  ('2f920203-a4a6-5aad-bee8-e50a48076ebf', 'Hopea brachyptera', 'Hopea', 'brachyptera', 'Dipterocarpaceae', 'endemic', 'Hopea brachyptera is a philippine endemic tree in Dipterocarpaceae. CDFP habitat record: Rare in primary lowland forest. It replaces the submitted Rubroshorea almonoides, whose documented native range does not include the Philippines.', 'Leaves are simple, alternate, and usually leathery, with pinnate side veins; stipules and venation help separate dipterocarp genera.', 'The trunk is typically straight and resin-bearing; mature bark may become fissured or scaly, but color and texture must be checked for this species.', 'Small bisexual, five-parted flowers are borne in branched clusters; petals, stamens, and calyx lobes require close inspection.', 'The fruit is a one-seeded nut enclosed by a persistent calyx; enlarged wing-like calyx lobes aid wind dispersal and identification.', 'A single recalcitrant seed is enclosed in the nut and normally loses viability quickly if allowed to dry.', 'medium', 10, 30, 5, 12, 'slow', TRUE, TRUE, 'Critically Endangered', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Critically Endangered', 'Rubroshorea almonoides', 'Endemic to the Philippines. MINDANAO: Zamboanga.', 'Rare in primary lowland forest.'),
  ('346b5b0d-5bde-5fb7-b474-f0c9588bbd1c', 'Rubroshorea ovata', 'Rubroshorea', 'ovata', 'Dipterocarpaceae', 'native', 'Rubroshorea ovata is a philippine native tree in Dipterocarpaceae. CDFP habitat record: Primary forests. 0-900(-1500)m.', 'Leaves are simple, alternate, and usually leathery, with pinnate side veins; stipules and venation help separate dipterocarp genera.', 'The trunk is typically straight and resin-bearing; mature bark may become fissured or scaly, but color and texture must be checked for this species.', 'Small bisexual, five-parted flowers are borne in branched clusters; petals, stamens, and calyx lobes require close inspection.', 'The fruit is a one-seeded nut enclosed by a persistent calyx; enlarged wing-like calyx lobes aid wind dispersal and identification.', 'A single recalcitrant seed is enclosed in the nut and normally loses viability quickly if allowed to dry.', 'large', 18, 45, 7, 18, 'slow', TRUE, TRUE, 'Least Concern', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Endangered', 'Rubroshorea ovata', 'Borneo, Malay Peninsula, Philippines, Sumatra. MINDANAO: Agusan, Agusan del Norte, Misamis, Misamis Oriental, Zamboanga, Zamboanga del Norte (photos).', 'Primary forests. 0-900(-1500)m.'),
  ('b986c9ac-d8da-5a34-a930-5148aa169e47', 'Dipterocarpus validus', 'Dipterocarpus', 'validus', 'Dipterocarpaceae', 'native', 'Dipterocarpus validus is a philippine native tree in Dipterocarpaceae. CDFP habitat record: Hagakhak. Common and frequently gregarious both in primary and secondary forests. There is some evidence of hybridization with Dipterocarpus kunstleri in the Philippines. 0-300m.', 'Leaves are simple, alternate, and usually leathery, with pinnate side veins; stipules and venation help separate dipterocarp genera.', 'The trunk is typically straight and resin-bearing; mature bark may become fissured or scaly, but color and texture must be checked for this species.', 'Small bisexual, five-parted flowers are borne in branched clusters; petals, stamens, and calyx lobes require close inspection.', 'The fruit is a one-seeded nut enclosed by a persistent calyx; enlarged wing-like calyx lobes aid wind dispersal and identification.', 'A single recalcitrant seed is enclosed in the nut and normally loses viability quickly if allowed to dry.', 'large', 18, 45, 7, 18, 'slow', TRUE, TRUE, 'Least Concern', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Dipterocarpus validus', 'Borneo, Philippines. BASILAN, CEBU, LEYTE, LUZON: Aurora, Cagayan, Camarines, Camarines Sur, Isabela, Laguna, NCR, Nueva Ecija, Quezon, Rizal, MARINDUQUE, MINDANAO: Agusan, Agusan del Norte, Davao, Misamis Occidental, Surigao, Zamboanga, MINDORO, NEGROS, PANAY, SAMAR.', 'Hagakhak. Common and frequently gregarious both in primary and secondary forests. There is some evidence of hybridization with Dipterocarpus kunstleri in the Philippines. 0-300m.'),
  ('e54cd621-002a-5650-b809-5bb9d0cbbec4', 'Dipterocarpus gracilis', 'Dipterocarpus', 'gracilis', 'Dipterocarpaceae', 'native', 'Dipterocarpus gracilis is a philippine native tree in Dipterocarpaceae. CDFP habitat record: Panau. Often gregarious in seasonal semi-evergreen dipterocarp forest on red soils; becoming scattered, rare, and confined to fertile red soils in everwet areas. 0-800m.', 'Leaves are simple, alternate, and usually leathery, with pinnate side veins; stipules and venation help separate dipterocarp genera.', 'The trunk is typically straight and resin-bearing; mature bark may become fissured or scaly, but color and texture must be checked for this species.', 'Small bisexual, five-parted flowers are borne in branched clusters; petals, stamens, and calyx lobes require close inspection.', 'The fruit is a one-seeded nut enclosed by a persistent calyx; enlarged wing-like calyx lobes aid wind dispersal and identification.', 'A single recalcitrant seed is enclosed in the nut and normally loses viability quickly if allowed to dry.', 'large', 18, 45, 7, 18, 'slow', TRUE, TRUE, 'Vulnerable', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Vulnerable', 'Dipterocarpus gracilis', 'Andaman Isls, Bangladesh, Borneo, Cambodia, India, Java, Malay Peninsula, Myanmar, Philippines, Sumatra, Thailand. GUIMARAS, LUZON: Albay, Bataan, Bulacan, Cagayan, Camarines, Ilocos Sur, Isabela, Laguna, NCR, Nueva Ecija, Nueva Vizcaya, Pangasinan, Quezon, Rizal, Zambales, MARINDUQUE, MINDANAO: Agusan del Norte, Agusan del Sur, Cotabato, Davao, Surigao, Zamboanga, Zamboanga del Norte, MINDORO, NEGROS, PALAWAN, POLILLO, SAMAR.', 'Panau. Often gregarious in seasonal semi-evergreen dipterocarp forest on red soils; becoming scattered, rare, and confined to fertile red soils in everwet areas. 0-800m.'),
  ('67943db1-d584-5f48-9223-bf60e24ca794', 'Dipterocarpus alatus', 'Dipterocarpus', 'alatus', 'Dipterocarpaceae', 'native', 'Dipterocarpus alatus is a philippine native tree in Dipterocarpaceae. CDFP habitat record: Hairy-leaf apitong. Primary mixed dipterocarp forest in seasonal areas. Rare. 450-550m (photos).', 'Leaves are simple, alternate, and usually leathery, with pinnate side veins; stipules and venation help separate dipterocarp genera.', 'The trunk is typically straight and resin-bearing; mature bark may become fissured or scaly, but color and texture must be checked for this species.', 'Small bisexual, five-parted flowers are borne in branched clusters; petals, stamens, and calyx lobes require close inspection.', 'The fruit is a one-seeded nut enclosed by a persistent calyx; enlarged wing-like calyx lobes aid wind dispersal and identification.', 'A single recalcitrant seed is enclosed in the nut and normally loses viability quickly if allowed to dry.', 'large', 18, 45, 7, 18, 'slow', TRUE, TRUE, 'Vulnerable', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Vulnerable', 'Dipterocarpus alatus', 'Andaman Isls, Bangladesh, Cambodia, India, Laos, Malay Peninsula, Myanmar, Philippines, Sri Lanka, Thailand, Vietnam. LEYTE (photos), LUZON: Abra, Bataan, Isabela (photos), Nueva Vizcaya.', 'Hairy-leaf apitong. Primary mixed dipterocarp forest in seasonal areas. Rare. 450-550m (photos).'),
  ('97e584e3-cf83-5057-a2be-b96d17f4383f', 'Hopea malibato', 'Hopea', 'malibato', 'Dipterocarpaceae', 'endemic', 'Hopea malibato is a philippine endemic tree in Dipterocarpaceae. CDFP habitat record: Yakal-kaliot. Primary evergreen dipterocarp forests in aseasonal areas. 0-700m.', 'Leaves are simple, alternate, and usually leathery, with pinnate side veins; stipules and venation help separate dipterocarp genera.', 'The trunk is typically straight and resin-bearing; mature bark may become fissured or scaly, but color and texture must be checked for this species.', 'Small bisexual, five-parted flowers are borne in branched clusters; petals, stamens, and calyx lobes require close inspection.', 'The fruit is a one-seeded nut enclosed by a persistent calyx; enlarged wing-like calyx lobes aid wind dispersal and identification.', 'A single recalcitrant seed is enclosed in the nut and normally loses viability quickly if allowed to dry.', 'medium', 10, 30, 5, 12, 'slow', TRUE, TRUE, 'Vulnerable', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Critically Endangered', 'Hopea malibato', 'Endemic to the Philippines. BASILAN, LEYTE, LUZON: Albay, Aurora (photos), Cagayan, Camarines, Isabela (photos), Laguna, Nueva Ecija, Pangasinan, Quezon, Sorsogon, Zambales, MASBATE, MINDANAO: Agusan, Agusan del Norte, Zamboanga, MINDORO, NEGROS, PANAY, POLILLO, SAMAR, SIBUYAN.', 'Yakal-kaliot. Primary evergreen dipterocarp forests in aseasonal areas. 0-700m.'),
  ('ddaf99df-4c91-59bc-8755-81da74a96154', 'Hopea mindanensis', 'Hopea', 'mindanensis', 'Dipterocarpaceae', 'endemic', 'Hopea mindanensis is a philippine endemic tree in Dipterocarpaceae. CDFP habitat record: Primary lowland evergreen forests. 100-600m. It replaces the submitted Pterocarpus woodii, whose documented native range does not include the Philippines.', 'Leaves are simple, alternate, and usually leathery, with pinnate side veins; stipules and venation help separate dipterocarp genera.', 'The trunk is typically straight and resin-bearing; mature bark may become fissured or scaly, but color and texture must be checked for this species.', 'Small bisexual, five-parted flowers are borne in branched clusters; petals, stamens, and calyx lobes require close inspection.', 'The fruit is a one-seeded nut enclosed by a persistent calyx; enlarged wing-like calyx lobes aid wind dispersal and identification.', 'A single recalcitrant seed is enclosed in the nut and normally loses viability quickly if allowed to dry.', 'medium', 10, 30, 5, 12, 'slow', TRUE, TRUE, 'Endangered', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Critically Endangered', 'Pterocarpus woodii', 'Endemic to the Philippines. BASILAN; MINDANAO: Zamboanga Sibugay, Zamboanga del Norte, Zamboanga del Sur.', 'Primary lowland evergreen forests. 100-600m.'),
  ('9f00aa8a-768d-5ee4-aad9-b5fcffb3c17d', 'Hopea quisumbingiana', 'Hopea', 'quisumbingiana', 'Dipterocarpaceae', 'endemic', 'Hopea quisumbingiana is a philippine endemic tree in Dipterocarpaceae. CDFP habitat record: Low-elevation, everwet primary forest. 0-700m. It replaces the submitted Afzelia martabanica, whose documented native range does not include the Philippines.', 'Leaves are simple, alternate, and usually leathery, with pinnate side veins; stipules and venation help separate dipterocarp genera.', 'The trunk is typically straight and resin-bearing; mature bark may become fissured or scaly, but color and texture must be checked for this species.', 'Small bisexual, five-parted flowers are borne in branched clusters; petals, stamens, and calyx lobes require close inspection.', 'The fruit is a one-seeded nut enclosed by a persistent calyx; enlarged wing-like calyx lobes aid wind dispersal and identification.', 'A single recalcitrant seed is enclosed in the nut and normally loses viability quickly if allowed to dry.', 'medium', 10, 30, 5, 12, 'slow', TRUE, TRUE, 'Endangered', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Critically Endangered', 'Afzelia martabanica', 'Endemic to the Philippines. BOHOL, possibly HOMONHON, and SAMAR.', 'Low-elevation, everwet primary forest. 0-700m.'),
  ('5bf79eba-adc8-5d3c-8f87-35cf94d035d8', 'Parkia speciosa', 'Parkia', 'speciosa', 'Fabaceae', 'native', 'Parkia speciosa is a philippine native tree in Fabaceae. CDFP habitat record: Lowland forests. 0-900(-1420)m. The submitted name Parkia harbesonii is retained as an audit alias.', 'Leaves are twice pinnate with many very small leaflets, producing a fine-textured crown.', 'Bark is gray-brown and becomes rough or shallowly fissured with age.', 'Numerous small flowers form dense hanging heads on long stalks and are commonly pollinated at night.', 'Long, flattened pods hang in clusters and become dark at maturity.', 'Several hard seeds lie in rows inside each pod, often surrounded by pulp.', 'large', 15, 35, 10, 22, 'moderate', TRUE, TRUE, 'Least Concern', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Other Threatened Species', 'Parkia harbesonii', 'Borneo, Malay Peninsula, Philippines, Sumatra, Thailand. PALAWAN.', 'Lowland forests. 0-900(-1420)m.'),
  ('ddba571e-c168-5103-af6b-d55ecf7614f0', 'Goniothalamus amuyon', 'Goniothalamus', 'amuyon', 'Annonaceae', 'native', 'Goniothalamus amuyon is a philippine native tree in Annonaceae. CDFP habitat record: Forests at low and medium elevations. 50-1372m.', 'Leaves are simple, alternate, entire, and arranged in two ranks along the twigs.', 'Twigs and bark may be aromatic when bruised; avoid destructive bark sampling.', 'Thick, three-petaled flowers are borne singly or in small groups, often directly from older twigs.', 'The fruit is an aggregate of separate fleshy monocarps attached to one receptacle.', 'Each monocarp contains one or more firm seeds.', 'small', 3, 12, 2, 6, 'slow', TRUE, TRUE, 'Vulnerable', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Goniothalamus amuyon', 'Philippines, Taiwan. BOHOL, CATANDUANES (photos), CEBU, LUZON: Abra, Batangas, Bulacan, Camarines Norte, Ilocos Norte, Ilocos Sur, Laguna, Pangasinan, Quezon, Rizal, MINDANAO, MINDORO, NEGROS, ?PANAY, SAMAR, SIBUYAN.', 'Forests at low and medium elevations. 50-1372m.'),
  ('5b4bcc4a-5fd3-5553-a2c3-0d6e1608d862', 'Vatica elliptica', 'Vatica', 'elliptica', 'Dipterocarpaceae', 'endemic', 'Vatica elliptica is a philippine endemic tree in Dipterocarpaceae. CDFP habitat record: Known from only two historical collections; mature fruit has not been documented in the Philippine checklist. It replaces the submitted Cananga brandisiana, whose documented native range does not include the Philippines.', 'Leaves are simple, alternate, and usually leathery, with pinnate side veins; stipules and venation help separate dipterocarp genera.', 'The trunk is typically straight and resin-bearing; mature bark may become fissured or scaly, but color and texture must be checked for this species.', 'Small bisexual, five-parted flowers are borne in branched clusters; petals, stamens, and calyx lobes require close inspection.', 'The fruit is a one-seeded nut enclosed by a persistent calyx; enlarged wing-like calyx lobes aid wind dispersal and identification.', 'A single recalcitrant seed is enclosed in the nut and normally loses viability quickly if allowed to dry.', 'medium', 10, 30, 5, 12, 'slow', TRUE, TRUE, 'Critically Endangered', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Critically Endangered', 'Cananga brandisiana', 'Endemic to the Philippines. MINDANAO: Zamboanga.', 'Known from only two historical collections; mature fruit has not been documented in the Philippine checklist.'),
  ('ee354559-0195-5112-b32d-aa1fab11b22a', 'Pinus merkusii', 'Pinus', 'merkusii', 'Pinaceae', 'native', 'Pinus merkusii is a philippine native tree in Pinaceae. CDFP habitat record: 60-2000m.', 'Adult foliage consists of long needle-like leaves held in bundles, with sheath and needle characters used for identification.', 'Mature trunks develop thick, plated or deeply fissured bark that helps protect the tree from surface fire.', 'There are no true flowers; separate pollen cones and seed cones occur on the same tree.', 'Woody seed cones open at maturity; cone scale and prickle characters are diagnostic.', 'Seeds commonly bear a papery wing for wind dispersal.', 'large', 20, 45, 7, 18, 'moderate', TRUE, FALSE, 'Vulnerable', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Vulnerable', 'Pinus merkusii', 'LUZON: Bulacan, Rizal, Zambales, MINDORO, PALAWAN.', '60-2000m.'),
  ('1424a423-02be-5c31-8652-f8195a535414', 'Dillenia reifferscheidia', 'Dillenia', 'reifferscheidia', 'Dilleniaceae', 'endemic', 'Dillenia reifferscheidia is a philippine endemic tree in Dilleniaceae. CDFP habitat record: In primary and secondary forests, particularly in more humid regions. Low elevation to 1000m.', 'Leaves are large, alternate, prominently parallel-veined, and usually toothed, with a rough or corrugated appearance.', 'Bark is gray-brown and becomes shallowly fissured or flaky on older stems.', 'Large flowers have five broad petals and many yellow stamens, making flowering trees conspicuous.', 'The rounded aggregate fruit is enclosed by enlarged, persistent sepals.', 'Numerous small seeds are embedded in the fruit pulp.', 'medium', 8, 20, 5, 12, 'moderate', TRUE, TRUE, 'Near Threatened', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Other Threatened Species', 'Dillenia reifferscheidia', 'Endemic to the Philippines. CATANDUANES, LUZON: Albay, Cagayan, Isabela, Laguna, Quezon, Rizal, Sorsogon, MINDANAO: Davao Oriental, Surigao del Norte, NEGROS, PANAY.', 'In primary and secondary forests, particularly in more humid regions. Low elevation to 1000m.'),
  ('1f09f47f-4f4f-5713-9752-fe389c7c95b5', 'Lagerstroemia paniculata', 'Lagerstroemia', 'paniculata', 'Lythraceae', 'endemic', 'Lagerstroemia paniculata is a philippine endemic tree in Lythraceae. CDFP habitat record: 110m to 400m (photos).', 'Leaves are simple, opposite to subopposite, and entire; young twigs and lower leaf surfaces should be checked for hairs.', 'Bark becomes smooth and exfoliating in patches, producing a mottled trunk.', 'Many crinkled-petaled flowers are carried in large terminal panicles.', 'The fruit is a dry woody capsule that splits into valves.', 'Numerous flattened seeds have a papery wing.', 'medium', 10, 25, 5, 14, 'moderate', TRUE, TRUE, 'Near Threatened', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Lagerstroemia paniculata', 'Endemic to the Philippines. BILIRAN, CATANDUANES, LEYTE (photos), LUZON: Aurora, Cagayan, Camarines Sur, Ilocos Norte, Isabela, Laguna, Quezon (photos), Rizal, MINDANAO: Agusan del Norte (photos), PANAY (photos), SAMAR.', '110m to 400m (photos).'),
  ('b2787015-8145-5784-80c6-fd04861c924d', 'Polyspora luzonica', 'Polyspora', 'luzonica', 'Theaceae', 'endemic', 'Polyspora luzonica is a philippine endemic tree in Theaceae. CDFP habitat record: Primary forests, stream depressions and exposed ridges. 600-1300m. The submitted name Gordonia luzonica is retained as an audit alias. POWO currently treats the accepted name as endemic to the Philippines, while the CDFP entry displays an older broader range; endemic status follows POWO and the conflict is retained for review.', 'Leaves are simple, alternate, leathery, and often crowded near twig ends, with a finely toothed margin.', 'Bark is gray to brown and becomes rough or fissured on older trunks.', 'Showy white flowers have five petals and numerous yellow stamens.', 'The fruit is a woody capsule that opens into several valves.', 'Several flattened, winged seeds are released from the capsule.', 'large', 12, 30, 6, 15, 'slow', TRUE, TRUE, 'Least Concern', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines', 'Gordonia luzonica', 'New Guinea, Philippines. BILIRAN, CEBU (photos), DINAGAT (photos), LEYTE (photos), LUZON: Abra, Apayao (photos), Bataan, Benguet, Camarines Sur, Ifugao, La Union, Laguna, Mountain Province, Nueva Vizcaya, Quezon, Sorsogon, Zambales, MINDANAO: Bukidnon, Davao Oriental, Davao del Sur, Lanao, Misamis Occidental, Misamis Oriental (photos), Surigao, MINDORO, NEGROS, PALAWAN, PANAY.', 'Primary forests, stream depressions and exposed ridges. 600-1300m.'),
  ('dffcc586-6ebf-5b1b-b3db-396b01493fa2', 'Prunus pulgarensis', 'Prunus', 'pulgarensis', 'Rosaceae', 'endemic', 'Prunus pulgarensis is a philippine endemic tree in Rosaceae. CDFP habitat record: Montane forests at approximately 1000-1200m. The submitted name Prunus pulgarense is retained as an audit alias.', 'Leaves are alternate, simple, and usually finely toothed; glands on the petiole or blade may aid identification.', 'Bark is gray-brown and may show horizontal lenticels on younger stems.', 'Small five-petaled flowers bear numerous stamens and occur singly or in short clusters.', 'The fruit is a one-stoned drupe that changes color as it ripens.', 'A single seed is enclosed by the hard stone; do not assume edibility without a species-specific source.', 'medium', 8, 25, 4, 12, 'moderate', TRUE, TRUE, 'Endangered', 'IUCN Red List category reported by Co''s Digital Flora of the Philippines; Philippine DAO category: Other Threatened Species', 'Prunus pulgarense', 'Endemic to the Philippines. LUZON: Bataan, Benguet, Mountain Province; PALAWAN.', 'Montane forests at approximately 1000-1200m.');


DO $$
BEGIN
  IF (SELECT count(*) FROM _species_016_input) <> 50 THEN
    RAISE EXCEPTION '016 input must contain exactly 50 species';
  END IF;
  IF (SELECT count(DISTINCT lower(scientific_name)) FROM _species_016_input) <> 50 THEN
    RAISE EXCEPTION '016 input contains duplicate accepted scientific names';
  END IF;
END $$;

INSERT INTO species (
  id, scientific_name, genus, species_epithet, family, native_status,
  description, leaf_description, bark_description, flower_description,
  fruit_description, seed_description, growth_form, min_height_m,
  max_height_m, min_canopy_m, max_canopy_m, growth_rate, fruit_bearing,
  flowering, conservation_status, conservation_source, verification_status,
  verified_at, deleted_at
)
SELECT desired_id, scientific_name, genus, species_epithet, family, native_status,
       description, leaf_description, bark_description, flower_description,
       fruit_description, seed_description, growth_form, min_height_m,
       max_height_m, min_canopy_m, max_canopy_m, growth_rate, fruit_bearing,
       flowering, conservation_status, conservation_source, 'verified', now(), NULL
FROM _species_016_input
ON CONFLICT (scientific_name) DO UPDATE SET
  genus=EXCLUDED.genus, species_epithet=EXCLUDED.species_epithet,
  family=EXCLUDED.family, native_status=EXCLUDED.native_status,
  description=EXCLUDED.description, leaf_description=EXCLUDED.leaf_description,
  bark_description=EXCLUDED.bark_description, flower_description=EXCLUDED.flower_description,
  fruit_description=EXCLUDED.fruit_description, seed_description=EXCLUDED.seed_description,
  growth_form=EXCLUDED.growth_form, min_height_m=EXCLUDED.min_height_m,
  max_height_m=EXCLUDED.max_height_m, min_canopy_m=EXCLUDED.min_canopy_m,
  max_canopy_m=EXCLUDED.max_canopy_m, growth_rate=EXCLUDED.growth_rate,
  fruit_bearing=EXCLUDED.fruit_bearing, flowering=EXCLUDED.flowering,
  conservation_status=EXCLUDED.conservation_status,
  conservation_source=EXCLUDED.conservation_source,
  verification_status='verified', verified_at=now(), deleted_at=NULL;

CREATE TEMP TABLE _species_016 AS
SELECT s.id, i.* FROM _species_016_input i JOIN species s USING (scientific_name);

DELETE FROM species_names WHERE species_id IN (SELECT id FROM _species_016);
