DO $$
DECLARE bad_count integer;
BEGIN
  SELECT count(*) INTO bad_count FROM _species_016 x JOIN species s USING(scientific_name)
  WHERE s.verification_status <> 'verified' OR s.deleted_at IS NOT NULL
     OR s.description = '' OR s.leaf_description IS NULL OR s.bark_description IS NULL
     OR s.flower_description IS NULL OR s.fruit_description IS NULL OR s.seed_description IS NULL
     OR s.min_height_m IS NULL OR s.max_height_m IS NULL
     OR s.min_canopy_m IS NULL OR s.max_canopy_m IS NULL OR s.growth_rate IS NULL;
  IF bad_count <> 0 THEN RAISE EXCEPTION '016 profile validation failed for % species', bad_count; END IF;

  SELECT count(*) INTO bad_count FROM _species_016 x
  WHERE (SELECT count(*) FROM species_references r WHERE r.species_id=x.id AND r.notes LIKE 'KP-ADD-016:%') < 2
     OR NOT EXISTS (SELECT 1 FROM species_distribution d WHERE d.species_id=x.id)
     OR NOT EXISTS (SELECT 1 FROM species_purposes p WHERE p.species_id=x.id)
     OR (SELECT count(*) FROM species_planting_conditions c WHERE c.species_id=x.id) < 4;
  IF bad_count <> 0 THEN RAISE EXCEPTION '016 relationship validation failed for % species', bad_count; END IF;

  IF EXISTS (SELECT 1 FROM species WHERE scientific_name IN
    ('Parashorea densiflora','Shorea ciliata','Rubroshorea almonoides','Pterocarpus woodii','Afzelia martabanica','Cananga brandisiana')
    AND deleted_at IS NULL AND verification_status='verified') THEN
    RAISE EXCEPTION 'A rejected non-Philippine submitted taxon is active';
  END IF;
END $$;
